class SeedDict(TypedDict):
    key: str


@dataclass
class ListRecord:
    key: str | None = None
    name: str = ''
    description: str = ''
    seeds: list[SeedDict | str] = field(default_factory=list)

    @staticmethod
    def normalize_input_seed(seed: SeedDict | str) -> SeedDict | str:
        if isinstance(seed, str):
            if seed.startswith('/subjects/'):
                return seed
            else:
                return {'key': seed if seed.startswith('/') else olid_to_key(seed)}
        else:
            if seed['key'].startswith('/subjects/'):
                return seed['key'].split('/', 2)[-1]
            else:
                return seed

    @staticmethod
    def from_input():
        defaults = {'key': None, 'name': '', 'description': '', 'seeds': []}
        body = web.data()
        if body:
            form = {
                key: values[0]
                for key, values in parse_qs(body.decode('utf-8')).items()
            }
            # A flat default cannot coexist with indexed fields under that key.
            values = {
                key: value
                for key, value in defaults.items()
                if key not in form and not any(field.startswith(f'{key}--') for field in form)
            }
            values.update(form)
        else:
            values = web.input(**defaults)
        i = utils.unflatten(values)

        seed_values = i.seeds if isinstance(i.seeds, list) else [i.seeds]
        normalized_seeds = [
            ListRecord.normalize_input_seed(seed)
            for seed_list in seed_values
            for seed in (
                seed_list.split(',') if isinstance(seed_list, str) else [seed_list]
            )
            if (isinstance(seed, str) and seed)
            or (isinstance(seed, dict) and isinstance(seed.get('key'), str) and seed['key'])
        ]
        normalized_seeds = [
            seed
            for seed in normalized_seeds
            if seed and (isinstance(seed, str) or seed.get('key'))
        ]
        return ListRecord(
            key=i.key,
            name=i.name,
            description=i.description,
            seeds=normalized_seeds,
        )

    def to_thing_json(self):
        return {
            "key": self.key,
            "type": {"key": "/type/list"},
            "name": self.name,
            "description": self.description,
            "seeds": self.seeds,
        }


